insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (86, 5, 82, 100, 'سورة المائدة ٨٢ – ١٠٠', 'أقربهم مودّة، ولا تحرّموا الطيبات، وتحريم الخمر، وصيد المُحرِم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 86) = $j$[{"lbl": "الآيات ٨٢ – ٨٦", "q": "۞لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ ﴿٨٢﴾ وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ ﴿٨٣﴾ وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِينَ ﴿٨٤﴾ فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ ﴿٨٥﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿٨٦﴾", "w": [["عداوة", "بغض نفسي يجعل صاحبه بعيداً ممن يعاديه فلا يصله بخير، وقد يحمله على إرادة الشر بالعدو."], ["مودّة", "حب نفسي يجعل صاحبه يتقرّب إلى من يودّه بالخير ودفع الشر."], ["ورهباناً", "الرهبان: جمع راهب، وهو الرجل من النصارى يتبتّل وينقطع للعبادة في دير أو صومعة."], ["ما أُنزل إلى الرسول", "آيات القرآن الدالة على تشريف عيسى ووالدته ﵉، وأن عيسى عبد الله ورسوله."], ["الشاهدين", "جمع شاهد: من شهد لله بالوحدانية وللنبي محمد ﷺ بالرسالة واستقام على ذلك."], ["الصالحين", "جمع صالح: من أدّى حقوق الله كاملة، وأدّى حقوق الناس كاملة من الإحسان إليهم وكفّ الأذى عنهم."], ["فأثابهم الله بما قالوا", "جزاهم بما قالوا من الإيمان ووُفّقوا له من العمل جنات تجري من تحتها الأنهار."]], "m": "يخبر الله رسوله ﷺ أن أشد الناس عداوة للذين آمنوا اليهود والذين أشركوا؛ أما اليهود فلما توارثوه من إنكار الحق والوقوف في وجه دعاته، ولأن أملهم في إعادة مجدهم يتعارض مع الدعوة الإسلامية، وأما المشركون فلجهلهم وإسرافهم في المحرمات وما ألفوه من الخرافات. وأخبر أن أقربهم مودة للذين آمنوا الذين قالوا إنا نصارى، ذلك بأن منهم قسيسين، علماء يؤثرون العدل والرحمة غالباً، ورهباناً منقطعين عن الدنيا، وأنهم لا يستكبرون عن الحق، ولذا لما عمّت المادية المجتمعات النصرانية وانتشر فيها الإلحاد قلّت تلك المودة. ثم ذكر من أسلم منهم بمجرد سماع القرآن، كأصحمة النجاشي وجماعة كثيرة: إذا سمعوا ما أُنزل إلى الرسول ترى أعينهم تفيض من الدمع مما عرفوا من الحق، يقولون: ربنا آمنّا فاكتبنا مع الشاهدين، وما لنا لا نؤمن بالله وما جاءنا من الحق، ونطمع أن يدخلنا ربنا مع القوم الصالحين؟ فأثابهم الله بما قالوا جنات تجري من تحتها الأنهار خالدين فيها، وذلك جزاء المحسنين. والذين كفروا وكذّبوا بآياتنا أولئك أصحاب الجحيم.", "h": ["عظم عداوة اليهود والمشركين للإسلام والمسلمين.", "قرب النصارى الصادقين في نصرانيتهم من المسلمين.", "فضيلة التواضع، وقبح الكبر.", "فضل هذه الأمة وكرامتها على الأمم قبلها.", "فضل الكتابي إذا أسلم وحسن إسلامه.", "بيان مصير الكافرين والمكذبين، وهو خلودهم في نار جهنم.", "استعمال القرآن أسلوب الترغيب والترهيب بذكره الوعيد بعد الوعد."], "k": "«ترى أعينهم تفيض من الدمع مما عرفوا من الحق»… متى آخر مرة دمعت عيني وأنا أسمع القرآن؟"}, {"lbl": "الآيات ٨٧ – ٨٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿٨٧﴾ وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ ﴿٨٨﴾ لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّـٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّـٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٨٩﴾", "w": [["لا تحرّموا", "التحريم: المنع، أي لا تمتنعوا."], ["ما أحلّ الله لكم", "ما أباحه لكم وأذن فيه من نكاح وطعام وشراب."], ["حلالاً طيباً", "مباحاً غير مستقذر ولا مستخبث."], ["لا يؤاخذكم الله باللغو", "لا يعاقبكم الله باللغو، وهو ما كان بغير قصد اليمين."], ["عقّدتم الأيمان", "عزمتم عليها بقلوبكم بأن تفعلوا أو لا تفعلوا."], ["من أوسط", "أغلبه، لا من أعلاه ولا من أدناه."], ["أهليكم", "من زوجة وولد."], ["تحرير رقبة", "عتقها من الرق القائم بها."]], "m": "نزلت في بعض الصحابة، منهم عبد الله بن مسعود وعثمان بن مظعون، حضروا موعظة لرسول الله ﷺ فزهدوا في الدنيا وعزموا على التبتّل، فسألوا عائشة رضي الله عنها عن عبادته فكأنهم تقالّوها، فقال أحدهم: لا آتي النساء، وقال آخر: أصوم الدهر، وقال آخر: أقوم فلا أنام، فخطب ﷺ وقال: «ما بال أقوام يقولون كذا وكذا؟ إني لآكل اللحم، وأصوم وأفطر، وأصلي وأنام، وأتزوج النساء، فمن رغب عن سنتي فليس مني»، ونزلت: لا تحرّموا طيبات ما أحلّ الله لكم من طعام وشراب ونساء، ولا تعتدوا بمجاوزة الحلال إلى الحرام، وكلوا مما رزقكم الله حلالاً طيباً، واتقوا الله بترك الغلوّ والتنطّع، ولا رهبانية في الإسلام. ولما قالوا: قد حلفنا على ما عزمنا عليه، فماذا نصنع بأيماننا؟ بيّن لهم: لا يؤاخذكم الله باللغو في أيمانكم، كقول: لا والله وبلى والله، ولكن يؤاخذكم بما عقّدتم الأيمان، فكفّارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم، أو كسوتهم، أو تحرير رقبة مؤمنة، يتخيّر أيها شاء، فإن لم يجد فصيام ثلاثة أيام، ذلك كفارة أيمانكم إذا حلفتم، واحفظوا أيمانكم فلا تكثروا الحلف، كذلك يبيّن الله لكم آياته لعلكم تشكرون.", "h": ["حرمة تحريم ما أباح الله، كحرمة تحليل ما حرّم الله عز وجل.", "بيان مدى حرص الصحابة على طاعة الله، خوفاً من عقابه وطمعاً في إنعامه.", "حرمة الغلوّ في الدين والتنطّع فيه.", "بيان كفارة اليمين بالتفصيل.", "كراهة الإكثار من الحلف، وحرمة الحلف بغير الله تعالى مطلقاً.", "استحباب حنث من حلف على ترك مندوب أو فعل مكروه وتكفيره عن ذلك، أما إذا حلف أن يترك واجباً أو يأتي محرّماً فإن حنثه واجب وعليه الكفارة.", "الأيمان ثلاثة: لغو لا كفارة لها، وغموس يحلف فيها متعمّداً الكذب ولا كفارة لها إلا التوبة، ومكفّرة يتعمّد فيها الحلف ليفعل أو لا يفعل ثم يحنث."], "k": "«فمن رغب عن سنتي فليس مني»… هل أشدّد على نفسي في أمرٍ وسّعه الله؟ أم أتساهل فيما شدّد فيه؟"}, {"lbl": "الآيات ٩٠ – ٩٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٩٠﴾ إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ ﴿٩١﴾ وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٩٢﴾ لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿٩٣﴾", "w": [["الخمر", "كل مسكر كيفما كانت مادته، قلّ أو كثر."], ["الأنصاب", "جمع نصب: ما يُنصب للتقرّب به أو التبرّك أو التعظيم، كتماثيل الرؤساء والزعماء في العهد الحديث."], ["الأزلام", "عيدان يستقسمون بها في الجاهلية لمعرفة الخير من الشر، ومثلها قرعة الأنبياء وخط الرمل والحساب بالمسبحة."], ["رجس", "المستقذر حساً أو معنى، إذ المحرّمات كلها خبيثة."], ["من عمل الشيطان", "مما يزيّنه للناس ويرغّبهم فيه ليضلّهم."], ["فاجتنبوه", "اتركوه جانباً، فلا تقبلوا عليه بقلوبكم، وابتعدوا عنه بأبدانكم."], ["تفلحون", "تكملون وتسعدون في دنياكم وآخرتكم."], ["فهل أنتم منتهون", "أي انتهوا، فالاستفهام للأمر لا للاستخبار."], ["جناح فيما طعموا", "إثم فيما شربوا من الخمر وأكلوا من الميسر قبل التحريم."]], "m": "لما نهى الله المؤمنين عن تحريم ما أحلّ لهم، نهاهم عما لم يُحلّ وأمرهم باجتنابه لضرره بقلوبهم وأرواحهم: يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان، يزيّنه ويحسّنه، فاجتنبوه لعلكم تفلحون. إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء في الخمر والميسر، وأنتم كالجسم الواحد، ويصدّكم عن ذكر الله الذي هو عصمتكم، وعن الصلاة التي هي معراجكم إلى ربكم، فهل أنتم منتهون؟ أمرٌ بأبلغ صيغة لخطورة هذه المحرّمات الأربع، فقال عمر: انتهينا يا ربنا. وأطيعوا الله وأطيعوا الرسول واحذروا، فإن تولّيتم فاعلموا أنما على رسولنا البلاغ المبين. ولما سأل بعض الصحابة: ما بال إخواننا الذين ماتوا وهم يشربون الخمر؟ نزلت: ليس على الذين آمنوا وعملوا الصالحات جناح فيما طعموا قبل التحريم، إذا ما اتقوا محارم الله وآمنوا وعملوا الصالحات، ثم داموا على التقوى والإيمان والإحسان، والله يحب المحسنين.", "h": ["حرمة الخمر والقمار، وتعظيم الأنصاب، والاستقسام بالأزلام.", "وجوب الانتهاء من تعاطي هذه المحرّمات فوراً، وقول: انتهينا يا ربنا، كما قال عمر رضي الله عنه.", "بيان علة تحريم شرب الخمر ولعب الميسر، وهي إثارة العداوة والبغضاء، والصدّ عن ذكر الله وعن الصلاة، وهما قوام حياة المسلم الروحية.", "وجوب طاعة الله والرسول، والحذر من معصيتهما.", "وجوب التقوى حتى الموت، ووجوب الإحسان في المعتقد والقول والعمل."], "k": "«فهل أنتم منتهون؟»… ما العادة التي أحتاج أن أقول فيها اليوم: انتهيت يا رب؟"}, {"lbl": "الآيات ٩٤ – ٩٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ ﴿٩٤﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ ﴿٩٥﴾ أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٩٦﴾", "w": [["الصيد", "ما يُصاد من حيوان البر."], ["تناله أيديكم", "كبيض الطير وفراخه."], ["ورماحكم", "ما يُنال بها من الحيوان على اختلافه."], ["ليعلم الله من يخافه بالغيب", "ليُظهر بذلك الاختبار من يخافه بالغيب فلا يصيد."], ["فمن اعتدى بعد ذلك", "بأن صاد بعد ما بلغه التحريم."], ["وأنتم حُرُم", "جمع حرام، وهو المُحرِم لحج أو عمرة."], ["من النَّعَم", "الإبل والبقر والغنم."], ["ذوا عدل منكم", "صاحبا عدالة من أهل العلم."], ["وبال أمره", "ثقل جزاء ذنبه."], ["وللسيّارة", "المسافرين يتزوّدون به، وطعام البحر ما يقذفه إلى الساحل."]], "m": "ينادي الله المؤمنين ليعلمهم أنه يبتليهم بشيء من الصيد تناله أيديهم ورماحهم، ليُظهر من يخافه بالغيب؛ فحرّم عليهم الصيد وهم محرمون، ثم ابتلاهم بوجوده بين أيديهم بيسر، كما ابتلى بني إسرائيل في السبت، بيد أن المسلمين امتثلوا، وبنو إسرائيل عصوا فمُسخوا قردة، فمن اعتدى بعد ذلك فله عذاب أليم. ثم أكّد التحريم: لا تقتلوا الصيد وأنتم حرم، ومن قتله منكم متعمّداً فجزاء مثل ما قتل من النعم، يحكم به ذوا عدل منكم، فالنعامة تشبه الجمل، وبقرة الوحش تشبه البقرة، والغزال يشبه التيس، فإن شاء ساقه هدياً بالغ الكعبة لفقراء الحرم، وإن شاء اشترى بثمنه طعاماً وتصدّق به، وإن شاء صام عن كل نصف صاع يوماً، ليذوق وبال أمره، عفا الله عما سلف، ومن عاد فينتقم الله منه. ثم أحلّ لهم امتناناً صيد البحر وطعامه متاعاً لهم وللمسافرين، وحرّم عليهم صيد البر ما داموا حرماً، واتقوا الله الذي إليه تُحشرون.", "h": ["ابتلاء الله أصحاب رسول الله ﷺ بالحديبية بكثرة الصيد بين أيديهم مع تحريمه عليهم، فامتثلوا فكانوا خيراً من بني إسرائيل.", "تحريم الصيد على المحرم، إلا صيد البحر فإنه مباح له.", "بيان جزاء من صاد وهو محرم، وأنه جزاء مثل ما قتل من النعم.", "وجوب التحكيم فيما صاده المحرم، ولا يصح أن يكفّر الصائد بنفسه.", "صيد الحرم حرام على المحرمين من الناس والمحلّين."], "k": "«ليعلم الله من يخافه بالغيب»… ما المعصية السهلة المتاحة لي حين لا يراني أحد؟ وهل أتركها لأنه يراني؟"}, {"lbl": "الآيات ٩٧ – ١٠٠", "q": "۞جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَـٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٩٧﴾ ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٩٨﴾ مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ﴿٩٩﴾ قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٠٠﴾", "w": [["الكعبة", "كل بناء مربّع، والمراد بها بيت الله الحرام."], ["قياماً للناس", "يقوم به أمر دينهم بالحج والاعتمار، ودنياهم بأمن داخله وجبي ثمرات كل شيء إليه."], ["الشهر الحرام", "المراد الأشهر الحرم الأربعة: رجب وذو القعدة وذو الحجة والمحرّم."], ["الهدي", "ما يُهدى إلى البيت من الأنعام."], ["والقلائد", "جمع قلادة، ما يُقلّد به الهدي."], ["البلاغ", "بلاغ ما أُمر بإبلاغه."], ["ما تبدون وما تكتمون", "ما تُظهرون وما تُخفون."], ["الخبيث", "مقابل الطيب، وهو الحرام، عام في المحسوسات والمعاني."], ["أولي الألباب", "أصحاب العقول."]], "m": "جعل الله الكعبة البيت الحرام قياماً للناس، والمراد العرب في جاهليتهم، فمصالحهم قائمة على وجود البيت: يُحجّ ويُعتمر، ويأمن الآتي إليه والداخل في حرمه، وكذا الشهر الحرام والهدي والقلائد، كانت تقوم مقام السلطان بينهم فتحقّق الأمن والرخاء، في وقت لا دولة لهم فيه ولا نظام، ذلك لتعلموا أن الله يعلم ما في السموات وما في الأرض وأنه بكل شيء عليم، فاعبدوه وحده. اعلموا أن الله شديد العقاب وأن الله غفور رحيم، ما على الرسول إلا البلاغ، وقد بلّغ فأنذر وأعذر، والله يعلم ما تبدون وما تكتمون. ثم قال لرسوله: قل لا يستوي الخبيث والطيب، من المعتقدات والأقوال والأعمال والرجال والأموال، ولو أعجبك كثرة الخبيث، فالعبرة بالطيب النافع ولو كان قليلاً، فاتقوا الله يا أولي الألباب لعلكم تفلحون.", "h": ["بيان عظيم تدبير الله لخلقه، إذ أمّن مصالح قريش والعرب بما ألقى في قلوبهم من تعظيم البيت الحرام والشهر الحرام والهدي والقلائد، الأمر الذي لا يقدر عليه إلا الله.", "بيان مسؤولية الرسول ﷺ إزاء الناس، وأنها البلاغ لا غير، وقد بلّغ ﷺ.", "تقرير الحكمة القائلة: العبرة بالكيف لا بالكم؛ فمؤمن واحد أنفع من عشرة كفرة، ودرهم حلال خير من عشرة حرام، وركعتان متقبّلتان خير من عشر لا تُقبل.", "الأمر بالتقوى رجاء فلاح المتقين."], "k": "«ولو أعجبك كثرة الخبيث»… هل أنخدع بكثرة من يفعل الخطأ حولي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 86;
insert into public.tdb_cards(topic, i, body) select 86, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٢ – ٨٦", "q": "۞لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ ﴿٨٢﴾ وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ ﴿٨٣﴾ وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِينَ ﴿٨٤﴾ فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ ﴿٨٥﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿٨٦﴾", "w": [["عداوة", "بغض نفسي يجعل صاحبه بعيداً ممن يعاديه فلا يصله بخير، وقد يحمله على إرادة الشر بالعدو."], ["مودّة", "حب نفسي يجعل صاحبه يتقرّب إلى من يودّه بالخير ودفع الشر."], ["ورهباناً", "الرهبان: جمع راهب، وهو الرجل من النصارى يتبتّل وينقطع للعبادة في دير أو صومعة."], ["ما أُنزل إلى الرسول", "آيات القرآن الدالة على تشريف عيسى ووالدته ﵉، وأن عيسى عبد الله ورسوله."], ["الشاهدين", "جمع شاهد: من شهد لله بالوحدانية وللنبي محمد ﷺ بالرسالة واستقام على ذلك."], ["الصالحين", "جمع صالح: من أدّى حقوق الله كاملة، وأدّى حقوق الناس كاملة من الإحسان إليهم وكفّ الأذى عنهم."], ["فأثابهم الله بما قالوا", "جزاهم بما قالوا من الإيمان ووُفّقوا له من العمل جنات تجري من تحتها الأنهار."]], "m": "يخبر الله رسوله ﷺ أن أشد الناس عداوة للذين آمنوا اليهود والذين أشركوا؛ أما اليهود فلما توارثوه من إنكار الحق والوقوف في وجه دعاته، ولأن أملهم في إعادة مجدهم يتعارض مع الدعوة الإسلامية، وأما المشركون فلجهلهم وإسرافهم في المحرمات وما ألفوه من الخرافات. وأخبر أن أقربهم مودة للذين آمنوا الذين قالوا إنا نصارى، ذلك بأن منهم قسيسين، علماء يؤثرون العدل والرحمة غالباً، ورهباناً منقطعين عن الدنيا، وأنهم لا يستكبرون عن الحق، ولذا لما عمّت المادية المجتمعات النصرانية وانتشر فيها الإلحاد قلّت تلك المودة. ثم ذكر من أسلم منهم بمجرد سماع القرآن، كأصحمة النجاشي وجماعة كثيرة: إذا سمعوا ما أُنزل إلى الرسول ترى أعينهم تفيض من الدمع مما عرفوا من الحق، يقولون: ربنا آمنّا فاكتبنا مع الشاهدين، وما لنا لا نؤمن بالله وما جاءنا من الحق، ونطمع أن يدخلنا ربنا مع القوم الصالحين؟ فأثابهم الله بما قالوا جنات تجري من تحتها الأنهار خالدين فيها، وذلك جزاء المحسنين. والذين كفروا وكذّبوا بآياتنا أولئك أصحاب الجحيم.", "h": ["عظم عداوة اليهود والمشركين للإسلام والمسلمين.", "قرب النصارى الصادقين في نصرانيتهم من المسلمين.", "فضيلة التواضع، وقبح الكبر.", "فضل هذه الأمة وكرامتها على الأمم قبلها.", "فضل الكتابي إذا أسلم وحسن إسلامه.", "بيان مصير الكافرين والمكذبين، وهو خلودهم في نار جهنم.", "استعمال القرآن أسلوب الترغيب والترهيب بذكره الوعيد بعد الوعد."], "k": "«ترى أعينهم تفيض من الدمع مما عرفوا من الحق»… متى آخر مرة دمعت عيني وأنا أسمع القرآن؟"}, {"lbl": "الآيات ٨٧ – ٨٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿٨٧﴾ وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ ﴿٨٨﴾ لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّـٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّـٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٨٩﴾", "w": [["لا تحرّموا", "التحريم: المنع، أي لا تمتنعوا."], ["ما أحلّ الله لكم", "ما أباحه لكم وأذن فيه من نكاح وطعام وشراب."], ["حلالاً طيباً", "مباحاً غير مستقذر ولا مستخبث."], ["لا يؤاخذكم الله باللغو", "لا يعاقبكم الله باللغو، وهو ما كان بغير قصد اليمين."], ["عقّدتم الأيمان", "عزمتم عليها بقلوبكم بأن تفعلوا أو لا تفعلوا."], ["من أوسط", "أغلبه، لا من أعلاه ولا من أدناه."], ["أهليكم", "من زوجة وولد."], ["تحرير رقبة", "عتقها من الرق القائم بها."]], "m": "نزلت في بعض الصحابة، منهم عبد الله بن مسعود وعثمان بن مظعون، حضروا موعظة لرسول الله ﷺ فزهدوا في الدنيا وعزموا على التبتّل، فسألوا عائشة رضي الله عنها عن عبادته فكأنهم تقالّوها، فقال أحدهم: لا آتي النساء، وقال آخر: أصوم الدهر، وقال آخر: أقوم فلا أنام، فخطب ﷺ وقال: «ما بال أقوام يقولون كذا وكذا؟ إني لآكل اللحم، وأصوم وأفطر، وأصلي وأنام، وأتزوج النساء، فمن رغب عن سنتي فليس مني»، ونزلت: لا تحرّموا طيبات ما أحلّ الله لكم من طعام وشراب ونساء، ولا تعتدوا بمجاوزة الحلال إلى الحرام، وكلوا مما رزقكم الله حلالاً طيباً، واتقوا الله بترك الغلوّ والتنطّع، ولا رهبانية في الإسلام. ولما قالوا: قد حلفنا على ما عزمنا عليه، فماذا نصنع بأيماننا؟ بيّن لهم: لا يؤاخذكم الله باللغو في أيمانكم، كقول: لا والله وبلى والله، ولكن يؤاخذكم بما عقّدتم الأيمان، فكفّارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم، أو كسوتهم، أو تحرير رقبة مؤمنة، يتخيّر أيها شاء، فإن لم يجد فصيام ثلاثة أيام، ذلك كفارة أيمانكم إذا حلفتم، واحفظوا أيمانكم فلا تكثروا الحلف، كذلك يبيّن الله لكم آياته لعلكم تشكرون.", "h": ["حرمة تحريم ما أباح الله، كحرمة تحليل ما حرّم الله عز وجل.", "بيان مدى حرص الصحابة على طاعة الله، خوفاً من عقابه وطمعاً في إنعامه.", "حرمة الغلوّ في الدين والتنطّع فيه.", "بيان كفارة اليمين بالتفصيل.", "كراهة الإكثار من الحلف، وحرمة الحلف بغير الله تعالى مطلقاً.", "استحباب حنث من حلف على ترك مندوب أو فعل مكروه وتكفيره عن ذلك، أما إذا حلف أن يترك واجباً أو يأتي محرّماً فإن حنثه واجب وعليه الكفارة.", "الأيمان ثلاثة: لغو لا كفارة لها، وغموس يحلف فيها متعمّداً الكذب ولا كفارة لها إلا التوبة، ومكفّرة يتعمّد فيها الحلف ليفعل أو لا يفعل ثم يحنث."], "k": "«فمن رغب عن سنتي فليس مني»… هل أشدّد على نفسي في أمرٍ وسّعه الله؟ أم أتساهل فيما شدّد فيه؟"}, {"lbl": "الآيات ٩٠ – ٩٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٩٠﴾ إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ ﴿٩١﴾ وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٩٢﴾ لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿٩٣﴾", "w": [["الخمر", "كل مسكر كيفما كانت مادته، قلّ أو كثر."], ["الأنصاب", "جمع نصب: ما يُنصب للتقرّب به أو التبرّك أو التعظيم، كتماثيل الرؤساء والزعماء في العهد الحديث."], ["الأزلام", "عيدان يستقسمون بها في الجاهلية لمعرفة الخير من الشر، ومثلها قرعة الأنبياء وخط الرمل والحساب بالمسبحة."], ["رجس", "المستقذر حساً أو معنى، إذ المحرّمات كلها خبيثة."], ["من عمل الشيطان", "مما يزيّنه للناس ويرغّبهم فيه ليضلّهم."], ["فاجتنبوه", "اتركوه جانباً، فلا تقبلوا عليه بقلوبكم، وابتعدوا عنه بأبدانكم."], ["تفلحون", "تكملون وتسعدون في دنياكم وآخرتكم."], ["فهل أنتم منتهون", "أي انتهوا، فالاستفهام للأمر لا للاستخبار."], ["جناح فيما طعموا", "إثم فيما شربوا من الخمر وأكلوا من الميسر قبل التحريم."]], "m": "لما نهى الله المؤمنين عن تحريم ما أحلّ لهم، نهاهم عما لم يُحلّ وأمرهم باجتنابه لضرره بقلوبهم وأرواحهم: يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان، يزيّنه ويحسّنه، فاجتنبوه لعلكم تفلحون. إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء في الخمر والميسر، وأنتم كالجسم الواحد، ويصدّكم عن ذكر الله الذي هو عصمتكم، وعن الصلاة التي هي معراجكم إلى ربكم، فهل أنتم منتهون؟ أمرٌ بأبلغ صيغة لخطورة هذه المحرّمات الأربع، فقال عمر: انتهينا يا ربنا. وأطيعوا الله وأطيعوا الرسول واحذروا، فإن تولّيتم فاعلموا أنما على رسولنا البلاغ المبين. ولما سأل بعض الصحابة: ما بال إخواننا الذين ماتوا وهم يشربون الخمر؟ نزلت: ليس على الذين آمنوا وعملوا الصالحات جناح فيما طعموا قبل التحريم، إذا ما اتقوا محارم الله وآمنوا وعملوا الصالحات، ثم داموا على التقوى والإيمان والإحسان، والله يحب المحسنين.", "h": ["حرمة الخمر والقمار، وتعظيم الأنصاب، والاستقسام بالأزلام.", "وجوب الانتهاء من تعاطي هذه المحرّمات فوراً، وقول: انتهينا يا ربنا، كما قال عمر رضي الله عنه.", "بيان علة تحريم شرب الخمر ولعب الميسر، وهي إثارة العداوة والبغضاء، والصدّ عن ذكر الله وعن الصلاة، وهما قوام حياة المسلم الروحية.", "وجوب طاعة الله والرسول، والحذر من معصيتهما.", "وجوب التقوى حتى الموت، ووجوب الإحسان في المعتقد والقول والعمل."], "k": "«فهل أنتم منتهون؟»… ما العادة التي أحتاج أن أقول فيها اليوم: انتهيت يا رب؟"}, {"lbl": "الآيات ٩٤ – ٩٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ ﴿٩٤﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ ﴿٩٥﴾ أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٩٦﴾", "w": [["الصيد", "ما يُصاد من حيوان البر."], ["تناله أيديكم", "كبيض الطير وفراخه."], ["ورماحكم", "ما يُنال بها من الحيوان على اختلافه."], ["ليعلم الله من يخافه بالغيب", "ليُظهر بذلك الاختبار من يخافه بالغيب فلا يصيد."], ["فمن اعتدى بعد ذلك", "بأن صاد بعد ما بلغه التحريم."], ["وأنتم حُرُم", "جمع حرام، وهو المُحرِم لحج أو عمرة."], ["من النَّعَم", "الإبل والبقر والغنم."], ["ذوا عدل منكم", "صاحبا عدالة من أهل العلم."], ["وبال أمره", "ثقل جزاء ذنبه."], ["وللسيّارة", "المسافرين يتزوّدون به، وطعام البحر ما يقذفه إلى الساحل."]], "m": "ينادي الله المؤمنين ليعلمهم أنه يبتليهم بشيء من الصيد تناله أيديهم ورماحهم، ليُظهر من يخافه بالغيب؛ فحرّم عليهم الصيد وهم محرمون، ثم ابتلاهم بوجوده بين أيديهم بيسر، كما ابتلى بني إسرائيل في السبت، بيد أن المسلمين امتثلوا، وبنو إسرائيل عصوا فمُسخوا قردة، فمن اعتدى بعد ذلك فله عذاب أليم. ثم أكّد التحريم: لا تقتلوا الصيد وأنتم حرم، ومن قتله منكم متعمّداً فجزاء مثل ما قتل من النعم، يحكم به ذوا عدل منكم، فالنعامة تشبه الجمل، وبقرة الوحش تشبه البقرة، والغزال يشبه التيس، فإن شاء ساقه هدياً بالغ الكعبة لفقراء الحرم، وإن شاء اشترى بثمنه طعاماً وتصدّق به، وإن شاء صام عن كل نصف صاع يوماً، ليذوق وبال أمره، عفا الله عما سلف، ومن عاد فينتقم الله منه. ثم أحلّ لهم امتناناً صيد البحر وطعامه متاعاً لهم وللمسافرين، وحرّم عليهم صيد البر ما داموا حرماً، واتقوا الله الذي إليه تُحشرون.", "h": ["ابتلاء الله أصحاب رسول الله ﷺ بالحديبية بكثرة الصيد بين أيديهم مع تحريمه عليهم، فامتثلوا فكانوا خيراً من بني إسرائيل.", "تحريم الصيد على المحرم، إلا صيد البحر فإنه مباح له.", "بيان جزاء من صاد وهو محرم، وأنه جزاء مثل ما قتل من النعم.", "وجوب التحكيم فيما صاده المحرم، ولا يصح أن يكفّر الصائد بنفسه.", "صيد الحرم حرام على المحرمين من الناس والمحلّين."], "k": "«ليعلم الله من يخافه بالغيب»… ما المعصية السهلة المتاحة لي حين لا يراني أحد؟ وهل أتركها لأنه يراني؟"}, {"lbl": "الآيات ٩٧ – ١٠٠", "q": "۞جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَـٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ﴿٩٧﴾ ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٩٨﴾ مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ﴿٩٩﴾ قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٠٠﴾", "w": [["الكعبة", "كل بناء مربّع، والمراد بها بيت الله الحرام."], ["قياماً للناس", "يقوم به أمر دينهم بالحج والاعتمار، ودنياهم بأمن داخله وجبي ثمرات كل شيء إليه."], ["الشهر الحرام", "المراد الأشهر الحرم الأربعة: رجب وذو القعدة وذو الحجة والمحرّم."], ["الهدي", "ما يُهدى إلى البيت من الأنعام."], ["والقلائد", "جمع قلادة، ما يُقلّد به الهدي."], ["البلاغ", "بلاغ ما أُمر بإبلاغه."], ["ما تبدون وما تكتمون", "ما تُظهرون وما تُخفون."], ["الخبيث", "مقابل الطيب، وهو الحرام، عام في المحسوسات والمعاني."], ["أولي الألباب", "أصحاب العقول."]], "m": "جعل الله الكعبة البيت الحرام قياماً للناس، والمراد العرب في جاهليتهم، فمصالحهم قائمة على وجود البيت: يُحجّ ويُعتمر، ويأمن الآتي إليه والداخل في حرمه، وكذا الشهر الحرام والهدي والقلائد، كانت تقوم مقام السلطان بينهم فتحقّق الأمن والرخاء، في وقت لا دولة لهم فيه ولا نظام، ذلك لتعلموا أن الله يعلم ما في السموات وما في الأرض وأنه بكل شيء عليم، فاعبدوه وحده. اعلموا أن الله شديد العقاب وأن الله غفور رحيم، ما على الرسول إلا البلاغ، وقد بلّغ فأنذر وأعذر، والله يعلم ما تبدون وما تكتمون. ثم قال لرسوله: قل لا يستوي الخبيث والطيب، من المعتقدات والأقوال والأعمال والرجال والأموال، ولو أعجبك كثرة الخبيث، فالعبرة بالطيب النافع ولو كان قليلاً، فاتقوا الله يا أولي الألباب لعلكم تفلحون.", "h": ["بيان عظيم تدبير الله لخلقه، إذ أمّن مصالح قريش والعرب بما ألقى في قلوبهم من تعظيم البيت الحرام والشهر الحرام والهدي والقلائد، الأمر الذي لا يقدر عليه إلا الله.", "بيان مسؤولية الرسول ﷺ إزاء الناس، وأنها البلاغ لا غير، وقد بلّغ ﷺ.", "تقرير الحكمة القائلة: العبرة بالكيف لا بالكم؛ فمؤمن واحد أنفع من عشرة كفرة، ودرهم حلال خير من عشرة حرام، وركعتان متقبّلتان خير من عشر لا تُقبل.", "الأمر بالتقوى رجاء فلاح المتقين."], "k": "«ولو أعجبك كثرة الخبيث»… هل أنخدع بكثرة من يفعل الخطأ حولي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (87, 5, 101, 120, 'سورة المائدة ١٠١ – ١٢٠', 'لا تسألوا عن أشياء، و«عليكم أنفسكم»، والمائدة، وختام السورة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 87) = $j$[{"lbl": "الآيات ١٠١ – ١٠٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ﴿١٠١﴾ قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ ﴿١٠٢﴾ مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿١٠٣﴾ وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ ﴿١٠٤﴾", "w": [["إن تُبدَ لكم", "تظهر لكم تضرّكم."], ["عفا الله عنها", "سكت عنها فلم يذكرها، أو لم يؤاخذكم بها."], ["سألها قوم", "طلبها غيركم من الأمم السابقة."], ["ما جعل الله", "ما شرع."], ["بحيرة ولا سائبة", "البحيرة: الناقة تُبحر أذنها أي تُشق، والسائبة: الناقة تُسيّب."], ["ولا وصيلة ولا حام", "الوصيلة: الناقة يكون أول إنتاجها أنثى، والحام: الجمل يُحمى ظهره للآلهة."], ["ما أنزل الله", "من الحق والخير."], ["ما وجدنا عليه آباءنا", "من الباطل والضلال."]], "m": "أكثر الناس على رسول الله ﷺ الأسئلة حتى قال: «لا تسألوني اليوم عن شيء إلا بيّنته لكم»، فقام عبد الله بن حذافة، وكان يُدعى إلى غير أبيه، فقال: من أبي؟ فقال: «أبوك حذافة»، وقال ﷺ: «إن الله قد فرض عليكم الحج فحجّوا» فسأله رجل: أفي كل عام؟ فنزلت: يا أيها الذين آمنوا لا تسألوا عن أشياء إن تُبدَ لكم تسؤكم، وإن تسألوا عنها حين ينزل القرآن تُبدَ لكم، أما قبل نزول القرآن بها فلا ينبغي لأنه من إحفاء رسول الله وأذيته، عفا الله عنها والله غفور حليم. قد سألها قوم من قبلكم ثم أصبحوا بها كافرين، لأنهم كُلّفوا ما لم يطيقوا جزاء تعنّتهم فتركوا العمل بها. ثم قال: ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام، ولكن الذين كفروا يفترون على الله الكذب وأكثرهم لا يعقلون، وأول من سيّب السوائب وغيّر دين إسماعيل عمرو بن لُحيّ، رآه رسول الله ﷺ يجرّ أمعاءه في النار. وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول قالوا: حسبنا ما وجدنا عليه آباءنا، أوَلو كان آباؤهم لا يعلمون شيئاً ولا يهتدون؟", "h": ["كراهية الإلحاف في السؤال والتقعّر في الأسئلة والتنطّع فيها.", "حرمة الابتداع في الدين، وأنه سبب وجود الشرك في الناس.", "وجوب ردّ المختلف فيه إلى الكتاب والسنة، والرضا بحكمهما.", "حرمة تقليد الجهال واتباعهم في أباطيلهم."], "k": "«حسبنا ما وجدنا عليه آباءنا»… ما العادة التي ورثتها ولم أعرضها يوماً على الكتاب والسنة؟"}, {"lbl": "الآية ١٠٥", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٠٥﴾", "w": [["آمنوا", "صدّقوا الله ورسوله واستجابوا لهما بفعل المأمور وترك المنهي."], ["عليكم أنفسكم", "ألزموا أنفسكم هدايتها وإصلاحها."], ["إذا اهتديتم", "إلى معرفة الحق ولزوم طريقه."], ["إلى الله مرجعكم جميعاً", "ضالّين ومهتدين."], ["فينبّئكم", "يخبركم بأعمالكم ويجازيكم بها."]], "m": "ينادي الله عباده المؤمنين: عليكم أنفسكم، ألزموها الهداية والطهارة بالإيمان والعمل الصالح، وأبعدوها عن الشرك والمعاصي، لا يضرّكم من ضلّ إذا اهتديتم، إذ لا تزر وازرة وزر أخرى. إلا أن من الاهتداء الأمر بالمعروف والنهي عن المنكر، فإن تركه المؤمنون لا يُعتبرون مهتدين، إذ بالسكوت عن المنكر يكثر وينتشر حتى يضلّ المؤمنون، ولذا قام أبو بكر الصديق رضي الله عنه خطيباً فقال: يا أيها الناس إنكم تقرؤون هذه الآية وتضعونها على غير موضعها، وإني سمعت رسول الله ﷺ يقول: «إن الناس إذا رأوا المنكر ولم يغيّروه يوشك أن يعمّهم الله بعقاب». إلى الله مرجعكم جميعاً فينبّئكم بما كنتم تعملون، وعدٌ لمن أطاع ووعيدٌ لمن عصى.", "h": ["وجوب إصلاح المؤمن نفسه وتطهيرها من آثار الشرك والمعاصي، وذلك بالإيمان والعمل الصالح.", "ضلال الناس لا يضرّ المؤمن إذا أمرهم بالمعروف ونهاهم عن المنكر.", "تقرير مبدأ البعث الآخر.", "للعمل أكبر الأثر في سعادة الإنسان أو شقائه."], "k": "«عليكم أنفسكم»… هل أنشغل بعيوب غيري عن إصلاح نفسي؟ وهل أنصح بالمعروف حين يلزمني؟"}, {"lbl": "الآيات ١٠٦ – ١٠٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ ﴿١٠٦﴾ فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿١٠٧﴾ ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿١٠٨﴾", "w": [["شهادة بينكم", "الشهادة: قول صادر عن علم حاصل بالبصر أو البصيرة."], ["إن ارتبتم", "شككتم في سلامة قولهما وعدالته."], ["فإن عُثر", "وُقف على خيانة منهما فيما عُهد إليهما حفظه."], ["أدنى", "أقرب."], ["على وجهها", "صحيحة كما هي، لا نقص فيها ولا زيادة."], ["الفاسقين", "الذين لم يلتزموا بطاعة الله ورسوله في الأمر والنهي."]], "m": "ما زال السياق في إرشاد المؤمنين: يا أيها الذين آمنوا، إذا حضر أحدكم الموت حين الوصية، فليشهد عليها اثنان ذوا عدل من المسلمين، أو آخران من غيركم إن كنتم مسافرين ولم يوجد مع المحتضر إلا غير مسلم، فإن شككتم في صدقهما فأوقفوهما بعد صلاة العصر ليحلفا بالله: لا نشتري بأيماننا ثمناً قليلاً ولو كان المشهود له ذا قربى، ولا نكتم شهادة الله، إنا إذاً لمن الآثمين. فإن وُجد أنهما خانا أو كذبا، فآخران من ورثة الميت يقومان مقامهما فيحلفان: لشهادتنا أحق من شهادتهما وما اعتدينا، إنا إذاً لمن الظالمين، فيُردّ إلى الورثة ما أخفاه الشاهدان. ذلك أقرب أن يأتوا بالشهادة على وجهها، أو يخافوا أن تُردّ أيمان بعد أيمانهم فيُفضحوا، واتقوا الله واسمعوا، والله لا يهدي القوم الفاسقين.", "h": ["مشروعية الوصية في الحضر والسفر معاً، والحث عليها والترغيب فيها.", "وجوب الإشهاد على الوصية.", "جواز شهادة غير المسلم على الوصية إذا تعذّر وجود مسلم.", "استحباب الحلف بعد صلاة العصر تغليظاً في شأن اليمين.", "مشروعية تحليف الشهود إذا ارتاب القاضي فيهم أو شك في صدقهم."], "k": "هل كتبت وصيتي؟ وهل حقوق الناس عندي مكتوبة واضحة لو جاء الأجل فجأة؟"}, {"lbl": "الآيات ١٠٩ – ١١١", "q": "۞يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿١٠٩﴾ إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَـٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿١١٠﴾ وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ ﴿١١١﴾", "w": [["يوم يجمع الله الرسل", "اذكر يوم يجمع الله الرسل، وذلك يوم القيامة."], ["الغيوب", "جمع غيب، وهو ما غاب عن العيون فلا يُدرك بالحواس."], ["أيّدتك", "قوّيتك ونصرتك."], ["بروح القدس", "جبريل ﵇."], ["وكهلاً", "الكهل: من تجاوز سن الشباب."], ["الكتاب", "الخط والكتابة."], ["والحكمة", "فهم أسرار الشرع، والإصابة في الأمور كلها."], ["تخلق من الطين كهيئة الطير", "تقدّر هيئة كصورة الطير."], ["الأكمه والأبرص", "الأكمه: من وُلد أعمى، والأبرص: من به مرض البرص."], ["تُخرج الموتى", "أحياءً من قبورهم."], ["الحواريّون", "جمع حواري، وهو صادق الحب في السر والعلن."]], "m": "يحذّر الله عباده من هول يوم يجمع الرسل فيسألهم وهو أعلم بهم: ماذا أُجبتم؟ فيذهلون ويفوّضون الأمر إليه: لا علم لنا إنك أنت علام الغيوب؛ فإذا كان هذا حال الرسل فكيف بمن دونهم؟ ويخصّ عيسى ﵇ بالكلام في هذا الموقف، لأن أمتين ضلّتا فيه: اليهود قالوا ساحر وابن زنى، والنصارى قالوا هو الله وابن الله، فيخاطبه وهم يسمعون: يا عيسى ابن مريم اذكر نعمتي عليك وعلى والدتك، فأنت عبدي ورسولي وأمك أمتي: إذ أيّدتك بجبريل، تكلّم الناس في المهد وكهلاً، وفيه بشرى لمريم أنه يكبر، وسيعود إلى الأرض ويكلّم الناس كهلاً، وإذ علّمتك الكتابة والحكمة والتوراة والإنجيل، وإذ تخلق من الطين كهيئة الطير بإذني فتنفخ فيها فتكون طيراً بإذني، وتبرئ الأكمه والأبرص بإذني، وإذ تُخرج الموتى بإذني، وإذ كففت بني إسرائيل عنك حين همّوا بقتلك، فقال الذين كفروا منهم إن هذا إلا سحر مبين. وإذ أوحيت إلى الحواريين أن آمنوا بي وبرسولي، قالوا آمنّا واشهد بأننا مسلمون.", "h": ["شدة هول يوم القيامة وصعوبة الموقف، حتى إن الرسل ليذهلون.", "وجوب الاستعداد لذلك اليوم بتقوى الله تعالى.", "توبيخ اليهود والنصارى، بتفريط اليهود في عيسى وغلوّ النصارى فيه.", "بيان إكرام الله تعالى لعيسى، وما حباه به من الفضل والإنعام.", "ثبوت معجزات عيسى ﵇ وتقريرها."], "k": "«ماذا أُجبتم؟»… لو سُئلت عن رسالة نبيي ﷺ إليّ، فبماذا أجبتها في حياتي؟"}, {"lbl": "الآيات ١١٢ – ١١٥", "q": "إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿١١٢﴾ قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّـٰهِدِينَ ﴿١١٣﴾ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿١١٤﴾ قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿١١٥﴾", "w": [["هل يستطيع", "هل يطيع ويرضى."], ["مائدة من السماء", "المائدة: الخوان وما يوضع عليه من طعام، والمراد هنا الطعام."], ["وتطمئن قلوبنا", "تسكن بزيادة اليقين فيها."], ["ونكون عليها من الشاهدين", "نشهد أنها نزلت من السماء."], ["عيداً", "يوماً يعود علينا كل عام نذكر الله فيه ونشكره."], ["وآية منك", "علامة منك على قدرتك ورحمتك ونبوة نبيك."], ["فمن يكفر بعدُ منكم", "بعد نزول المائدة، أيها السائلون."], ["أحداً من العالمين", "من الناس أجمعين."]], "m": "إذ قال الحواريون: يا عيسى ابن مريم هل يستطيع ربك أن ينزّل علينا مائدة من السماء؟ ولما كان قولهم هذا دالاً على شك في نفوسهم، قال: اتقوا الله إن كنتم مؤمنين، فلا تقولوا مثل هذا. فاعتذروا: نريد أن نأكل منها وتطمئن قلوبنا ونعلم أن قد صدقتنا ونكون عليها من الشاهدين. فقال عيسى ﵇ ضارعاً: اللهم ربنا أنزل علينا مائدة من السماء تكون لنا عيداً لأولنا وآخرنا، وآية منك على وحدانيتك وقدرتك وصدق رسالتي، وارزقنا وأنت خير الرازقين. فأجابه ربه: إني منزّلها عليكم، وقد أنزلها، فمن يكفر بعد منكم فإني أعذّبه عذاباً لا أعذّبه أحداً من العالمين، ولذا مُسخ من كفر منهم قردة وخنازير.", "h": ["جفاء اليهود وسوء أدبهم مع أنبيائهم، إذ قالوا لموسى: «اذهب أنت وربك فقاتلا»، وقالوا لعيسى: «هل يستطيع ربك».", "في قول عيسى لهم: «اتقوا الله» دلالة على أنهم قالوا الباطل، كما أن قولهم: «ونعلم أن قد صدقتنا» دال على شكهم وارتيابهم.", "مشروعية الأعياد الدينية لعبادة الله بالصلاة والذكر شكراً لله، وفي الإسلام عيدان: الأضحى والفطر.", "من أشد الناس عذاباً يوم القيامة: آل فرعون، والمنافقون، ومن كفر من أهل المائدة."], "k": "«وتطمئن قلوبنا»… هل أطلب طمأنينة قلبي بالآيات والمعجزات، أم بذكر الله والعمل؟"}, {"lbl": "الآيات ١١٦ – ١٢٠", "q": "وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿١١٦﴾ مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿١١٧﴾ إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١١٨﴾ قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١١٩﴾ لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ ﴿١٢٠﴾", "w": [["إلهين", "معبودين يُعبدان من دوني."], ["سبحانك", "تنزيهاً لك وتقديساً."], ["ما يكون لي", "ما ينبغي لي ولا يتأتّى لي ذلك."], ["الحكيم", "الذي يضع كل شيء في موضعه، فيُدخل المشرك النار والموحّد الجنة."], ["الصادقين", "جمع صادق، وهو من صدق ربه في عبادته وحده."], ["ورضوا عنه", "لأنه أثابهم بأعمالهم جنات تجري من تحتها الأنهار."], ["على كل شيء قدير", "على فعل أي شيء أراده، لا يعجزه بحال."]], "m": "يقول الله لرسوله ﷺ: اذكر لقومك إذ قال الله يوم يجمع الرسل: يا عيسى ابن مريم أأنت قلت للناس اتخذوني وأمي إلهين من دون الله؟ فيقول منزّهاً ربه: سبحانك ما يكون لي أن أقول ما ليس لي بحق، إن كنت قلته فقد علمته، تعلم ما في نفسي ولا أعلم ما في نفسك، إنك أنت علام الغيوب، ما قلت لهم إلا ما أمرتني به: أن اعبدوا الله ربي وربكم، وكنت عليهم شهيداً ما دمت فيهم، فلما توفّيتني برفعي إليك كنت أنت الرقيب عليهم، وأنت على كل شيء شهيد. إن تعذّبهم، من مات منهم على الشرك، فإنهم عبادك وأنت على ذلك قدير، وإن تغفر لهم، لمن مات على التوحيد، فإنك أنت العزيز الحكيم. فيجيبه ربه: هذا يوم ينفع الصادقين صدقهم، صدقوا الله في إيمانهم فعبدوه وحده، لهم جنات تجري من تحتها الأنهار خالدين فيها أبداً، رضي الله عنهم ورضوا عنه، ذلك الفوز العظيم. لله ملك السموات والأرض وما فيهن، وهو على كل شيء قدير.", "h": ["توبيخ النصارى في عرصات القيامة على تأليه عيسى ووالدته ﵉.", "براءة عيسى ﵇ من مشركي النصارى وأهل الكتاب.", "تعذيب المشركين وتنعيم الموحّدين قائم على مبدأ الحكمة الإلهية.", "فضيلة الصدق، وأنه نافع في الدنيا والآخرة، وفي الحديث: «عليكم بالصدق فإن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة».", "سؤال غير الله شيئاً ضرب من الباطل والشرك؛ لأن غير الله لا يملك شيئاً، ومن لا يملك كيف يعطي؟"], "k": "«هذا يوم ينفع الصادقين صدقهم»… في أي موضع من حياتي أحتاج أن أكون أصدق مع الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 87;
insert into public.tdb_cards(topic, i, body) select 87, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠١ – ١٠٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ﴿١٠١﴾ قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ ﴿١٠٢﴾ مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿١٠٣﴾ وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ ﴿١٠٤﴾", "w": [["إن تُبدَ لكم", "تظهر لكم تضرّكم."], ["عفا الله عنها", "سكت عنها فلم يذكرها، أو لم يؤاخذكم بها."], ["سألها قوم", "طلبها غيركم من الأمم السابقة."], ["ما جعل الله", "ما شرع."], ["بحيرة ولا سائبة", "البحيرة: الناقة تُبحر أذنها أي تُشق، والسائبة: الناقة تُسيّب."], ["ولا وصيلة ولا حام", "الوصيلة: الناقة يكون أول إنتاجها أنثى، والحام: الجمل يُحمى ظهره للآلهة."], ["ما أنزل الله", "من الحق والخير."], ["ما وجدنا عليه آباءنا", "من الباطل والضلال."]], "m": "أكثر الناس على رسول الله ﷺ الأسئلة حتى قال: «لا تسألوني اليوم عن شيء إلا بيّنته لكم»، فقام عبد الله بن حذافة، وكان يُدعى إلى غير أبيه، فقال: من أبي؟ فقال: «أبوك حذافة»، وقال ﷺ: «إن الله قد فرض عليكم الحج فحجّوا» فسأله رجل: أفي كل عام؟ فنزلت: يا أيها الذين آمنوا لا تسألوا عن أشياء إن تُبدَ لكم تسؤكم، وإن تسألوا عنها حين ينزل القرآن تُبدَ لكم، أما قبل نزول القرآن بها فلا ينبغي لأنه من إحفاء رسول الله وأذيته، عفا الله عنها والله غفور حليم. قد سألها قوم من قبلكم ثم أصبحوا بها كافرين، لأنهم كُلّفوا ما لم يطيقوا جزاء تعنّتهم فتركوا العمل بها. ثم قال: ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام، ولكن الذين كفروا يفترون على الله الكذب وأكثرهم لا يعقلون، وأول من سيّب السوائب وغيّر دين إسماعيل عمرو بن لُحيّ، رآه رسول الله ﷺ يجرّ أمعاءه في النار. وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول قالوا: حسبنا ما وجدنا عليه آباءنا، أوَلو كان آباؤهم لا يعلمون شيئاً ولا يهتدون؟", "h": ["كراهية الإلحاف في السؤال والتقعّر في الأسئلة والتنطّع فيها.", "حرمة الابتداع في الدين، وأنه سبب وجود الشرك في الناس.", "وجوب ردّ المختلف فيه إلى الكتاب والسنة، والرضا بحكمهما.", "حرمة تقليد الجهال واتباعهم في أباطيلهم."], "k": "«حسبنا ما وجدنا عليه آباءنا»… ما العادة التي ورثتها ولم أعرضها يوماً على الكتاب والسنة؟"}, {"lbl": "الآية ١٠٥", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿١٠٥﴾", "w": [["آمنوا", "صدّقوا الله ورسوله واستجابوا لهما بفعل المأمور وترك المنهي."], ["عليكم أنفسكم", "ألزموا أنفسكم هدايتها وإصلاحها."], ["إذا اهتديتم", "إلى معرفة الحق ولزوم طريقه."], ["إلى الله مرجعكم جميعاً", "ضالّين ومهتدين."], ["فينبّئكم", "يخبركم بأعمالكم ويجازيكم بها."]], "m": "ينادي الله عباده المؤمنين: عليكم أنفسكم، ألزموها الهداية والطهارة بالإيمان والعمل الصالح، وأبعدوها عن الشرك والمعاصي، لا يضرّكم من ضلّ إذا اهتديتم، إذ لا تزر وازرة وزر أخرى. إلا أن من الاهتداء الأمر بالمعروف والنهي عن المنكر، فإن تركه المؤمنون لا يُعتبرون مهتدين، إذ بالسكوت عن المنكر يكثر وينتشر حتى يضلّ المؤمنون، ولذا قام أبو بكر الصديق رضي الله عنه خطيباً فقال: يا أيها الناس إنكم تقرؤون هذه الآية وتضعونها على غير موضعها، وإني سمعت رسول الله ﷺ يقول: «إن الناس إذا رأوا المنكر ولم يغيّروه يوشك أن يعمّهم الله بعقاب». إلى الله مرجعكم جميعاً فينبّئكم بما كنتم تعملون، وعدٌ لمن أطاع ووعيدٌ لمن عصى.", "h": ["وجوب إصلاح المؤمن نفسه وتطهيرها من آثار الشرك والمعاصي، وذلك بالإيمان والعمل الصالح.", "ضلال الناس لا يضرّ المؤمن إذا أمرهم بالمعروف ونهاهم عن المنكر.", "تقرير مبدأ البعث الآخر.", "للعمل أكبر الأثر في سعادة الإنسان أو شقائه."], "k": "«عليكم أنفسكم»… هل أنشغل بعيوب غيري عن إصلاح نفسي؟ وهل أنصح بالمعروف حين يلزمني؟"}, {"lbl": "الآيات ١٠٦ – ١٠٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ ﴿١٠٦﴾ فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿١٠٧﴾ ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿١٠٨﴾", "w": [["شهادة بينكم", "الشهادة: قول صادر عن علم حاصل بالبصر أو البصيرة."], ["إن ارتبتم", "شككتم في سلامة قولهما وعدالته."], ["فإن عُثر", "وُقف على خيانة منهما فيما عُهد إليهما حفظه."], ["أدنى", "أقرب."], ["على وجهها", "صحيحة كما هي، لا نقص فيها ولا زيادة."], ["الفاسقين", "الذين لم يلتزموا بطاعة الله ورسوله في الأمر والنهي."]], "m": "ما زال السياق في إرشاد المؤمنين: يا أيها الذين آمنوا، إذا حضر أحدكم الموت حين الوصية، فليشهد عليها اثنان ذوا عدل من المسلمين، أو آخران من غيركم إن كنتم مسافرين ولم يوجد مع المحتضر إلا غير مسلم، فإن شككتم في صدقهما فأوقفوهما بعد صلاة العصر ليحلفا بالله: لا نشتري بأيماننا ثمناً قليلاً ولو كان المشهود له ذا قربى، ولا نكتم شهادة الله، إنا إذاً لمن الآثمين. فإن وُجد أنهما خانا أو كذبا، فآخران من ورثة الميت يقومان مقامهما فيحلفان: لشهادتنا أحق من شهادتهما وما اعتدينا، إنا إذاً لمن الظالمين، فيُردّ إلى الورثة ما أخفاه الشاهدان. ذلك أقرب أن يأتوا بالشهادة على وجهها، أو يخافوا أن تُردّ أيمان بعد أيمانهم فيُفضحوا، واتقوا الله واسمعوا، والله لا يهدي القوم الفاسقين.", "h": ["مشروعية الوصية في الحضر والسفر معاً، والحث عليها والترغيب فيها.", "وجوب الإشهاد على الوصية.", "جواز شهادة غير المسلم على الوصية إذا تعذّر وجود مسلم.", "استحباب الحلف بعد صلاة العصر تغليظاً في شأن اليمين.", "مشروعية تحليف الشهود إذا ارتاب القاضي فيهم أو شك في صدقهم."], "k": "هل كتبت وصيتي؟ وهل حقوق الناس عندي مكتوبة واضحة لو جاء الأجل فجأة؟"}, {"lbl": "الآيات ١٠٩ – ١١١", "q": "۞يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿١٠٩﴾ إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَـٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿١١٠﴾ وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ ﴿١١١﴾", "w": [["يوم يجمع الله الرسل", "اذكر يوم يجمع الله الرسل، وذلك يوم القيامة."], ["الغيوب", "جمع غيب، وهو ما غاب عن العيون فلا يُدرك بالحواس."], ["أيّدتك", "قوّيتك ونصرتك."], ["بروح القدس", "جبريل ﵇."], ["وكهلاً", "الكهل: من تجاوز سن الشباب."], ["الكتاب", "الخط والكتابة."], ["والحكمة", "فهم أسرار الشرع، والإصابة في الأمور كلها."], ["تخلق من الطين كهيئة الطير", "تقدّر هيئة كصورة الطير."], ["الأكمه والأبرص", "الأكمه: من وُلد أعمى، والأبرص: من به مرض البرص."], ["تُخرج الموتى", "أحياءً من قبورهم."], ["الحواريّون", "جمع حواري، وهو صادق الحب في السر والعلن."]], "m": "يحذّر الله عباده من هول يوم يجمع الرسل فيسألهم وهو أعلم بهم: ماذا أُجبتم؟ فيذهلون ويفوّضون الأمر إليه: لا علم لنا إنك أنت علام الغيوب؛ فإذا كان هذا حال الرسل فكيف بمن دونهم؟ ويخصّ عيسى ﵇ بالكلام في هذا الموقف، لأن أمتين ضلّتا فيه: اليهود قالوا ساحر وابن زنى، والنصارى قالوا هو الله وابن الله، فيخاطبه وهم يسمعون: يا عيسى ابن مريم اذكر نعمتي عليك وعلى والدتك، فأنت عبدي ورسولي وأمك أمتي: إذ أيّدتك بجبريل، تكلّم الناس في المهد وكهلاً، وفيه بشرى لمريم أنه يكبر، وسيعود إلى الأرض ويكلّم الناس كهلاً، وإذ علّمتك الكتابة والحكمة والتوراة والإنجيل، وإذ تخلق من الطين كهيئة الطير بإذني فتنفخ فيها فتكون طيراً بإذني، وتبرئ الأكمه والأبرص بإذني، وإذ تُخرج الموتى بإذني، وإذ كففت بني إسرائيل عنك حين همّوا بقتلك، فقال الذين كفروا منهم إن هذا إلا سحر مبين. وإذ أوحيت إلى الحواريين أن آمنوا بي وبرسولي، قالوا آمنّا واشهد بأننا مسلمون.", "h": ["شدة هول يوم القيامة وصعوبة الموقف، حتى إن الرسل ليذهلون.", "وجوب الاستعداد لذلك اليوم بتقوى الله تعالى.", "توبيخ اليهود والنصارى، بتفريط اليهود في عيسى وغلوّ النصارى فيه.", "بيان إكرام الله تعالى لعيسى، وما حباه به من الفضل والإنعام.", "ثبوت معجزات عيسى ﵇ وتقريرها."], "k": "«ماذا أُجبتم؟»… لو سُئلت عن رسالة نبيي ﷺ إليّ، فبماذا أجبتها في حياتي؟"}, {"lbl": "الآيات ١١٢ – ١١٥", "q": "إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿١١٢﴾ قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّـٰهِدِينَ ﴿١١٣﴾ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿١١٤﴾ قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿١١٥﴾", "w": [["هل يستطيع", "هل يطيع ويرضى."], ["مائدة من السماء", "المائدة: الخوان وما يوضع عليه من طعام، والمراد هنا الطعام."], ["وتطمئن قلوبنا", "تسكن بزيادة اليقين فيها."], ["ونكون عليها من الشاهدين", "نشهد أنها نزلت من السماء."], ["عيداً", "يوماً يعود علينا كل عام نذكر الله فيه ونشكره."], ["وآية منك", "علامة منك على قدرتك ورحمتك ونبوة نبيك."], ["فمن يكفر بعدُ منكم", "بعد نزول المائدة، أيها السائلون."], ["أحداً من العالمين", "من الناس أجمعين."]], "m": "إذ قال الحواريون: يا عيسى ابن مريم هل يستطيع ربك أن ينزّل علينا مائدة من السماء؟ ولما كان قولهم هذا دالاً على شك في نفوسهم، قال: اتقوا الله إن كنتم مؤمنين، فلا تقولوا مثل هذا. فاعتذروا: نريد أن نأكل منها وتطمئن قلوبنا ونعلم أن قد صدقتنا ونكون عليها من الشاهدين. فقال عيسى ﵇ ضارعاً: اللهم ربنا أنزل علينا مائدة من السماء تكون لنا عيداً لأولنا وآخرنا، وآية منك على وحدانيتك وقدرتك وصدق رسالتي، وارزقنا وأنت خير الرازقين. فأجابه ربه: إني منزّلها عليكم، وقد أنزلها، فمن يكفر بعد منكم فإني أعذّبه عذاباً لا أعذّبه أحداً من العالمين، ولذا مُسخ من كفر منهم قردة وخنازير.", "h": ["جفاء اليهود وسوء أدبهم مع أنبيائهم، إذ قالوا لموسى: «اذهب أنت وربك فقاتلا»، وقالوا لعيسى: «هل يستطيع ربك».", "في قول عيسى لهم: «اتقوا الله» دلالة على أنهم قالوا الباطل، كما أن قولهم: «ونعلم أن قد صدقتنا» دال على شكهم وارتيابهم.", "مشروعية الأعياد الدينية لعبادة الله بالصلاة والذكر شكراً لله، وفي الإسلام عيدان: الأضحى والفطر.", "من أشد الناس عذاباً يوم القيامة: آل فرعون، والمنافقون، ومن كفر من أهل المائدة."], "k": "«وتطمئن قلوبنا»… هل أطلب طمأنينة قلبي بالآيات والمعجزات، أم بذكر الله والعمل؟"}, {"lbl": "الآيات ١١٦ – ١٢٠", "q": "وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿١١٦﴾ مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿١١٧﴾ إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١١٨﴾ قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿١١٩﴾ لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ ﴿١٢٠﴾", "w": [["إلهين", "معبودين يُعبدان من دوني."], ["سبحانك", "تنزيهاً لك وتقديساً."], ["ما يكون لي", "ما ينبغي لي ولا يتأتّى لي ذلك."], ["الحكيم", "الذي يضع كل شيء في موضعه، فيُدخل المشرك النار والموحّد الجنة."], ["الصادقين", "جمع صادق، وهو من صدق ربه في عبادته وحده."], ["ورضوا عنه", "لأنه أثابهم بأعمالهم جنات تجري من تحتها الأنهار."], ["على كل شيء قدير", "على فعل أي شيء أراده، لا يعجزه بحال."]], "m": "يقول الله لرسوله ﷺ: اذكر لقومك إذ قال الله يوم يجمع الرسل: يا عيسى ابن مريم أأنت قلت للناس اتخذوني وأمي إلهين من دون الله؟ فيقول منزّهاً ربه: سبحانك ما يكون لي أن أقول ما ليس لي بحق، إن كنت قلته فقد علمته، تعلم ما في نفسي ولا أعلم ما في نفسك، إنك أنت علام الغيوب، ما قلت لهم إلا ما أمرتني به: أن اعبدوا الله ربي وربكم، وكنت عليهم شهيداً ما دمت فيهم، فلما توفّيتني برفعي إليك كنت أنت الرقيب عليهم، وأنت على كل شيء شهيد. إن تعذّبهم، من مات منهم على الشرك، فإنهم عبادك وأنت على ذلك قدير، وإن تغفر لهم، لمن مات على التوحيد، فإنك أنت العزيز الحكيم. فيجيبه ربه: هذا يوم ينفع الصادقين صدقهم، صدقوا الله في إيمانهم فعبدوه وحده، لهم جنات تجري من تحتها الأنهار خالدين فيها أبداً، رضي الله عنهم ورضوا عنه، ذلك الفوز العظيم. لله ملك السموات والأرض وما فيهن، وهو على كل شيء قدير.", "h": ["توبيخ النصارى في عرصات القيامة على تأليه عيسى ووالدته ﵉.", "براءة عيسى ﵇ من مشركي النصارى وأهل الكتاب.", "تعذيب المشركين وتنعيم الموحّدين قائم على مبدأ الحكمة الإلهية.", "فضيلة الصدق، وأنه نافع في الدنيا والآخرة، وفي الحديث: «عليكم بالصدق فإن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة».", "سؤال غير الله شيئاً ضرب من الباطل والشرك؛ لأن غير الله لا يملك شيئاً، ومن لا يملك كيف يعطي؟"], "k": "«هذا يوم ينفع الصادقين صدقهم»… في أي موضع من حياتي أحتاج أن أكون أصدق مع الله؟"}]$j$::jsonb) with ordinality x(e, i);
